for rec in records:
    if not rec.x_employee_id or not rec.x_resumption_date:
        continue

    emp = rec.x_employee_id
    res_date = rec.x_resumption_date
    if isinstance(res_date, str):
        res_date = datetime.date.fromisoformat(res_date)

    res_date_str = str(res_date)

    auto_name = rec.x_name
    if not auto_name or auto_name in ['Name', 'جديد', 'New']:
        auto_name = 'أمر مباشرة - %s - %s' % (emp.name or '', res_date_str)
        rec.write({'x_name': auto_name})

    target_leave = rec.x_leave_id
    if not target_leave:
        leaves = env['hr.leave'].search([
            ('employee_id', '=', emp.id),
            ('state', 'in', ['confirm', 'validate', 'validate1']),
            ('request_date_from', '<=', res_date_str),
            ('request_date_to', '>=', res_date_str)
        ], order='request_date_from desc', limit=1)
        if leaves:
            target_leave = leaves[0]
            rec.write({'x_leave_id': target_leave.id})

    if target_leave:
        l_from = target_leave.request_date_from
        l_to = target_leave.request_date_to
        if isinstance(l_from, str):
            l_from = datetime.date.fromisoformat(l_from)
        if isinstance(l_to, str):
            l_to = datetime.date.fromisoformat(l_to)

        orig_days = float(target_leave.number_of_days or 0.0)
        rec.write({'x_original_days': orig_days})

        leave_updates = {
            'x_original_end_date': l_to,
            'x_original_days': orig_days,
            'x_is_resumed': True,
            'x_pending_resumption': False,
            'x_resumption_warning': False,
            'x_resumption_date': res_date,
            'x_resumption_order_no': rec.x_order_number or '',
            'x_resumption_order_date': rec.x_order_date or False,
            'x_resumption_id': rec.id
        }

        if res_date <= l_from:
            leave_updates.update({
                'number_of_days': 0.0,
                'state': 'refuse'
            })
            target_leave.with_context(tracking_disable=True).write(leave_updates)
            rec.write({
                'x_actual_days': 0.0,
                'x_state': 'confirmed'
            })
            actual_days = 0.0
        elif res_date > l_to:
            # Resumption is after the leave already ended naturally
            target_leave.with_context(tracking_disable=True).write(leave_updates)
            rec.write({
                'x_actual_days': orig_days,
                'x_state': 'confirmed'
            })
            actual_days = orig_days
        else:
            new_end_date = res_date - datetime.timedelta(days=1)
            actual_days = float((new_end_date - l_from).days + 1)
            dt_to = datetime.datetime.combine(new_end_date, datetime.time(12, 0, 0))

            leave_updates.update({
                'request_date_to': new_end_date,
                'date_to': dt_to,
                'number_of_days': actual_days
            })
            target_leave.with_context(tracking_disable=True).write(leave_updates)
            rec.write({
                'x_actual_days': actual_days,
                'x_state': 'confirmed'
            })

        order_str = ('رقم (%s)' % rec.x_order_number) if rec.x_order_number else 'بدون رقم'
        if rec.x_order_date:
            order_str += (' في %s' % rec.x_order_date)
        msg = "تم إصدار أمر مباشرة بالدوام للموظف بتاريخ %s بموجب الأمر الإداري %s. تمت مباشرة الموظف واعتماد الإجازة." % (
            res_date_str,
            order_str
        )
        target_leave.message_post(body=msg)
    else:
        rec.write({
            'x_state': 'confirmed',
            'x_actual_days': 0.0
        })

    # Clear pending resumption warnings on employee
    emp.write({
        'x_pending_resumption': False,
        'x_resumption_status': 'resumed',
        'x_resumption_warning': False
    })

    slips = env['hr.payslip'].search([
        ('employee_id', '=', emp.id),
        ('state', '=', 'draft'),
        ('date_from', '<=', res_date_str),
        ('date_to', '>=', res_date_str)
    ])
    if slips:
        slips.write({
            'x_pending_resumption': False,
            'x_resumption_status': 'resumed',
            'x_resumption_warning': False
        })
        action_1307 = env['ir.actions.server'].browse(1307)
        if action_1307:
            action_1307.with_context(active_ids=slips.ids, active_model='hr.payslip').run()

    # Auto-register resumption in x_hr_admin_order
    try:
        admin_order_obj = env['x_hr_admin_order']
        order_num = rec.x_admin_order_number or ('مباشرة/%s' % rec.id)
        existing_order = admin_order_obj.search([('x_order_number', '=', order_num)], limit=1)
        vals_order = {
            'x_order_number': order_num,
            'x_order_date': rec.x_resumption_date or fields.Date.today(),
            'x_title': 'أمر مباشرة بالدوام للموظف: %s' % (rec.x_employee_id.name or ''),
            'x_order_type': 'resumption',
            'x_target_type': 'employee',
            'x_employee_ids': [(6, 0, [rec.x_employee_id.id])],
            'x_company_id': rec.x_employee_id.company_id.id if rec.x_employee_id.company_id else False,
            'x_department_id': rec.x_employee_id.department_id.id if rec.x_employee_id.department_id else False,
            'x_notes': 'أمر مباشرة بالدوام بعد إجازة. تاريخ المباشرة: %s. بيان: %s' % (rec.x_resumption_date or '', rec.x_notes or ''),
            'x_state': 'active'
        }
        if existing_order:
            existing_order.write(vals_order)
        else:
            admin_order_obj.create(vals_order)
    except Exception as e:
        pass

