for rec in records:
    name_str = 'أمر إداري رقم %s - %s' % (rec.x_order_number or '', rec.x_title or '')
    if rec.x_order_date:
        name_str += ' (%s)' % rec.x_order_date

    order_vals = {
        'x_name': name_str,
        'x_state': 'active'
    }

    # Calculate deduction schedule if penalty fields are present
    tot_amt = rec.x_penalty_amount or 0.0
    mon_amt = rec.x_deduction_monthly or 0.0
    st_date = rec.x_deduction_start_date or rec.x_order_date or False

    # Fallback to regex if not filled
    if mon_amt <= 0:
        txt = (rec.x_ocr_text or '') + ' ' + (rec.x_notes or '')
        m_inst = re.search(r'أقساط شهرية مقدارها \(?([0-9,]+)\)?|استقطاع.*مقدارها \(?([0-9,]+)\)?', txt)
        if m_inst:
            val_str = m_inst.group(1) or m_inst.group(2)
            mon_amt = float(val_str.replace(',', ''))
        m_tot = re.search(r'البالغة \(?([0-9,]+)\)?|بقيمة \(?([0-9,]+)\\)?', txt)
        if m_tot:
            val_str = m_tot.group(1) or m_tot.group(2)
            tot_amt = float(val_str.replace(',', ''))

    months_cnt = rec.x_deduction_months or 0
    last_amt = rec.x_deduction_last_amount or 0.0
    end_dt = rec.x_deduction_end_date or False

    if mon_amt > 0 and tot_amt > 0:
        if not months_cnt:
            months_cnt = int(tot_amt // mon_amt) + (1 if (tot_amt % mon_amt) > 0 else 0)
            order_vals['x_deduction_months'] = months_cnt
        if not last_amt:
            rem = tot_amt % mon_amt
            last_amt = rem if rem > 0 else mon_amt
            order_vals['x_deduction_last_amount'] = last_amt
        if not end_dt and st_date:
            try:
                parts = [int(p) for p in str(st_date).replace('/', '-').split('-')]
                if len(parts) == 3:
                    s_y, s_m, s_d = parts[0], parts[1], parts[2]
                    tot_m = s_m + (months_cnt - 1)
                    end_y = s_y + (tot_m - 1) // 12
                    end_m = (tot_m - 1) % 12 + 1
                    end_dt = '%04d-%02d-01' % (end_y, end_m)
                    order_vals['x_deduction_end_date'] = end_dt
            except Exception:
                pass

    rec.write(order_vals)

    # Sync with employees
    if rec.x_employee_ids:
        for emp in rec.x_employee_ids:
            if rec.id not in emp.x_admin_order_ids.ids:
                emp.sudo().write({'x_admin_order_ids': [(4, rec.id)]})

            if mon_amt > 0:
                emp_vals = {
                    'x_ded_other': mon_amt,
                }
                if months_cnt:
                    emp_vals['x_penalty_months'] = months_cnt
                if last_amt:
                    emp_vals['x_penalty_last_amount'] = last_amt
                if end_dt:
                    emp_vals['x_penalty_end_date'] = end_dt

                tot_wage = emp.x_total_wage or emp.x_original_wage or emp.wage or 0.0
                emp_vals['x_total_wage'] = tot_wage
                other_deds = (emp.x_ded_social_sec or 0.0) + (emp.x_ded_leaves or 0.0) + (emp.x_ded_delay or 0.0) + (emp.x_ded_advance or 0.0)
                emp_vals['x_net_wage'] = max(0.0, tot_wage - (other_deds + mon_amt))

                note_msg = 'استقطاع غرامة (%.0f د.ع شهرياً) بموجب أمر إداري رقم %s' % (mon_amt, rec.x_order_number or '')
                if tot_amt > 0:
                    note_msg += ': الإجمالي (%.0f د.ع)' % tot_amt
                if months_cnt:
                    note_msg += ' على %d أشهر' % months_cnt
                if st_date:
                    note_msg += ' تبدأ من %s' % st_date
                if end_dt:
                    note_msg += ' حتى آخر دفعة بتاريخ %s' % end_dt
                if last_amt and last_amt != mon_amt:
                    note_msg += ' بقيمة (%.0f د.ع)' % last_amt
                note_msg += ' لحين استيفاء كامل المبلغ'

                curr_notes = emp.x_payroll_notes or ''
                if note_msg not in curr_notes:
                    emp_vals['x_payroll_notes'] = (curr_notes + ' | ' + note_msg) if curr_notes else note_msg
                emp.sudo().write(emp_vals)

