            except Exception:
                board_d = datetime.date.today()

            # Close old driver log: drop-off time matches new driver's boarding time exactly!
            open_logs = env['fleet.vehicle.assignation.log'].search([
                ('vehicle_id', '=', vehicle.id),
                ('date_end', '=', False)
            ])
            for old in open_logs:
                old_notes = old.x_notes or ''
                handover_note = 'تسليم الشاحنة إلى (%s) بتاريخ ووقت: %s' % (new_driver.name, str(board_dt)[:16])
                full_note = (old_notes + ' | ' + handover_note) if old_notes else handover_note
                old.write({
                    'date_end': board_d,
                    'x_datetime_end': board_dt,
                    'x_notes': full_note,
                })

            vehicle.write({'driver_id': new_driver.id})

            curr_log = env['fleet.vehicle.assignation.log'].search([
                ('vehicle_id', '=', vehicle.id),
                ('driver_id', '=', new_driver.id),
                ('date_end', '=', False)
            ], limit=1, order='id desc')
            if curr_log:
                curr_log.write({
                    'date_start': board_d,
                    'x_datetime_start': board_dt,
                    'x_entry_datetime': entry_dt,
                    'x_notes': notes or False,
                })
            else:
                env['fleet.vehicle.assignation.log'].create({
                    'vehicle_id': vehicle.id,
                    'driver_id': new_driver.id,
                    'date_start': board_d,
                    'x_datetime_start': board_dt,
                    'x_entry_datetime': entry_dt,
                    'x_notes': notes or False,
                })

action = {'type': 'ir.actions.act_window_close'}
